        const timeoutSecs = rpcDeadlines("run_command", args).runnerSecs ?? RUN_COMMAND_DEFAULT_TIMEOUT_SECS;
        return await runReadOnlySandbox(
          sandboxed.argv[0],
          sandboxed.argv.slice(1),
          workspaceFd,
          timeoutSecs * 1000,
          this.turnSignal,
